fn first_over(limit: i32) -> i32 {
    let mut sum = 0;
    let mut i = 1;
    loop {
        sum += i;
        if sum > limit {
            break i;
        }
        i += 1;
    }
}

fn count_to(n: i32) -> i32 {
    let mut count = 0;
    loop {
        if count >= n { break; }
        count += 1;
    }
    count
}

fn find_first_negative(xs: &[i32]) -> i32 {
    let mut i = 0;
    loop {
        if i >= xs.len() { break -1; }
        if xs[i] < 0 { break i as i32; }
        i += 1;
    }
}

