fn double_until(start: i32, limit: i32) -> i32 {
    let mut x = start;
    if x <= 0 { return 0; }
    let mut count = 0;
    loop {
        if x >= limit { break; }
        x *= 2;
        count += 1;
    }
    count
}

fn sum_while(n: i32) -> i32 {
    let mut sum = 0;
    let mut i = 1;
    while i <= n {
        sum += i;
        i += 1;
    }
    sum
}

